# Project context (optional)
# Add only constraints that should guide OpenSpec artifacts and workflows.
# Include constraints an agent cannot infer by reading the code.
# Keep general project documentation and discoverable codebase facts out.
# Example:
#   context: |
#     Designs and tasks must cover Windows, macOS, and Linux
#     Write all artifacts in Spanish

# Per-artifact rules (optional)
# Add custom rules for specific artifacts.
# Example:
#   rules:
#     proposal:
#       - Keep proposals under 500 words
#       - Always state what is out of scope
#     tasks:
#       - Break tasks into chunks of max 2 hours

# Per-operation guidance (optional)
# Add advisory guidance for how apply and archive work should be conducted.
# This is separate from artifact rules above.
# Example:
#   operations:
#     apply:
#       guidance:
#         - Keep test summaries concise
#     archive:
#       guidance:
#         - Summarize the archive outcome before finishing
{ "name": "notes-api", "version": "0.1.0", "type": "module", "scripts": { "start": "node src/server.js", "test": "node --test" } }
# notes-api

A tiny JSON notes API. `npm start`, `npm test`.
import { createServer } from 'node:http';
import { listNotes, addNote, deleteNote } from './store.js';

export function handler(req, res) {
  const url = new URL(req.url, 'http://localhost');
  if (req.method === 'GET' && url.pathname === '/notes') return send(res, 200, listNotes());
  if (req.method === 'POST' && url.pathname === '/notes') {
    let body = '';
    req.on('data', (c) => (body += c));
    req.on('end', () => {
      const { text } = JSON.parse(body || '{}');
      if (!text) return send(res, 400, { error: 'text is required' });
      send(res, 201, addNote(text));
    });
    return;
  }
  const m = url.pathname.match(/^\/notes\/(\d+)$/);
  if (req.method === 'DELETE' && m) return deleteNote(Number(m[1])) ? send(res, 204) : send(res, 404, { error: 'not found' });
  send(res, 404, { error: 'not found' });
}

function send(res, status, data) {
  res.writeHead(status, { 'content-type': 'application/json' });
  res.end(data === undefined ? '' : JSON.stringify(data));
}

if (process.argv[1] === new URL(import.meta.url).pathname) createServer(handler).listen(3001);
const notes = [];
let nextId = 1;
export const listNotes = () => notes;
export function addNote(text) { const n = { id: nextId++, text, createdAt: new Date().toISOString() }; notes.push(n); return n; }
export function deleteNote(id) { const i = notes.findIndex((n) => n.id === id); if (i < 0) return false; notes.splice(i, 1); return true; }
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { addNote, listNotes, deleteNote } from '../src/store.js';
test('add and delete', () => { const n = addNote('hi'); assert.equal(listNotes().length, 1); assert.ok(deleteNote(n.id)); assert.equal(listNotes().length, 0); });

